with with_gaps as (select *, case when paid_at - lag(paid_at) over (partition by status order by paid_at, id) > interval 90 days then 1 else 0 end as is_new_burst from payments), islands as (select *, sum(is_new_burst) over (partition by status order by paid_at, id rows between unbounded preceding and current row) as session_id from with_gaps) select s.id, s.order_id, s.method, s.paid_at, s.session_id, case when method rlike '^(promptpay|cash)$' then 'EXTENDED' else 'GROUP_B' end as method_zone, (select min(p2.amount) from payments p2 where p2.order_id = s.order_id) as min_payment_amount from islands s
